-- Eden Strong — a year of daily devotions for women (365 days)
-- Built from the Eden Strong morning routine: the Ephesians 1 and 3 prayers,
-- the Word confessions, and the seven Morning Declarations.
--
-- Twelve monthly themes:
--   1  A Good Work Begun              (Philippians 1:6)
--   2  Eyes of My Heart               (Ephesians 1:17-20)
--   3  Rooted and Grounded in Love    (Ephesians 3:14-19)
--   4  Life to the Full               (John 10:10)
--   5  Healed and Whole               (Isaiah 53:4-5, Psalm 103, Proverbs 4:20-22)
--   6  Renewed Strength               (Isaiah 40:29-31)
--   7  Under His Wings                (Psalm 91, 121, 27)
--   8  Power, Love, and a Sound Mind  (2 Timothy 1:7, 2 Corinthians 10:3-5)
--   9  Peace That Guards              (Philippians 4:6-7)
--   10 Faith That Pleases Him         (Hebrews 11:6)
--   11 Favor and Fruitful Work        (Deuteronomy 28:12, Psalm 5:12)
--   12 A Light Wherever I Go          (Matthew 5:14)
--
-- Each day: title, verse (KJV, public domain), reflection, declaration,
-- prayer, a "strength step," and a journal prompt.
-- Shows only for Eden Strong members (edition = 'women').
-- Run once in the Supabase SQL Editor. Safe to run again: it replaces
-- the Eden Strong devotions and leaves every other devotion alone.

alter table daily_devotions add column if not exists edition text;
alter table daily_devotions add column if not exists title text;
alter table daily_devotions add column if not exists theme text;
alter table daily_devotions add column if not exists declaration text;
alter table daily_devotions add column if not exists prayer text;
alter table daily_devotions add column if not exists strength_step text;

-- Each brand gets its own Day 1, Day 2, Day 3...
alter table daily_devotions drop constraint if exists daily_devotions_day_number_key;
create unique index if not exists daily_devotions_edition_day on daily_devotions ((coalesce(edition, 'all')), day_number);

delete from daily_devotions where edition = 'women';


select count(*) as "Eden Strong devotions loaded" from daily_devotions where edition = 'women';
